import{_ as d,o as e,c as i,a2 as l}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"04 · 平行基线 W2–W5","description":"","frontmatter":{},"headers":[],"relativePath":"04-平行基线-W2-W5.md","filePath":"04-平行基线-W2-W5.md"}'),a={name:"04-平行基线-W2-W5.md"};function o(r,t,n,h,s,u){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="_04-·-平行基线-w2–w5" tabindex="-1">04 · 平行基线 W2–W5</h1><blockquote><p>同一张画，跑不同&quot;通道组合&quot;做业务层对照。差异不是参数差异，而是<strong>反馈机制差异</strong>（见 01 §3）。</p></blockquote><h2 id="_1-反馈类型回顾" tabindex="-1">1. 反馈类型回顾</h2><ul><li><strong>隐性纠错</strong>（W1）：不指出错误，模型先验沿你的线顺手修正 → 发现盲区</li><li><strong>显性纠错</strong>（W2/W3）：你必须先诊断，模型再改 → 训练诊断眼</li></ul><h2 id="_2-各基线" tabindex="-1">2. 各基线</h2><h3 id="w2-—-flux-2-klein-4b-指令修图-本地" tabindex="-1">W2 — FLUX.2 [klein] 4B 指令修图（本地）</h3><ul><li>官方确认（README 实测）：单模型支持文生图/单参考编辑/多参考编辑；<strong>约 8GB 显存可跑</strong>（官方原话 RTX 3090/4070 and up）；<strong>Apache-2.0</strong>；2026-01-15 发布</li><li>⚠️ 4060：显存达标但带宽低，分钟级；用 GGUF Q4_K + Qwen3-4B 编码器 + flux2-vae（下载见 02 §6）</li><li>⚠️ 接入：官方仓库是 stable-diffusion.cpp 路线；ComfyUI 接入以 ComfyUI-GGUF 文档为准（未验证）</li><li>来源：<a href="https://github.com/black-forest-labs/flux2" target="_blank" rel="noreferrer">https://github.com/black-forest-labs/flux2</a></li></ul><h3 id="w3-—-qwen-image-edit-指令修图-云端" tabindex="-1">W3 — Qwen-Image-Edit 指令修图（云端）</h3><ul><li>官方确认（README 实测）：20B、<strong>中英双语</strong>、外观编辑（局部增删改其余不变）+ 语义编辑（含<strong>风格迁移</strong>）、Apache-2.0</li><li>运行：8G 本地跑不动完整版 → Qwen Chat 网页 / 阿里云 API / 社区 ComfyUI 工作流（Qwen Image Edit 2511 Ultimate）配租卡</li><li>来源：<a href="https://huggingface.co/Qwen/Qwen-Image-Edit" target="_blank" rel="noreferrer">https://huggingface.co/Qwen/Qwen-Image-Edit</a></li></ul><h3 id="w4-—-flux-2-dev-32b-质量上限基准-可选" tabindex="-1">W4 — FLUX.2 [dev] 32B（质量上限基准，可选）</h3><ul><li>官方定位&quot;最高质量&quot;；非商用许可；24G+ 显存 → 租卡</li><li>用途：偶尔租一次出&quot;上限参考图&quot;，校准目标水位线</li></ul><h3 id="w5-—-老师风格通道-详见-05-06" tabindex="-1">W5 — 老师风格通道（详见 05 / 06）</h3><ul><li>路线 0：画师标签（NoobAI 用完整 Danbooru 训练，知名画师自带标签，零成本，先试）</li><li>路线 1：IP-Adapter 多参考风格跟随（零训练，即时）→ <a href="./05-风格路线-IPAdapter.html">05-风格路线-IPAdapter.md</a></li><li>路线 2：风格 LoRA（深拷贝，一次训练长期复用）→ <a href="./06-风格路线-LoRA.html">06-风格路线-LoRA.md</a></li></ul><h2 id="_3-对照表" tabindex="-1">3. 对照表</h2><table tabindex="0"><thead><tr><th>基线</th><th>机制</th><th>反馈类型</th><th>提示词语言</th><th>运行</th><th>成本</th><th>何时用</th></tr></thead><tbody><tr><td>W1 NoobAI 双通道</td><td>贴线重绘</td><td>隐性纠错</td><td>标签</td><td>本地 8G</td><td>¥0</td><td>日常主通道</td></tr><tr><td>W2 FLUX.2 klein</td><td>指令编辑</td><td>显性纠错</td><td>自然语言</td><td>本地 8G（慢）</td><td>¥0</td><td>练诊断眼</td></tr><tr><td>W3 Qwen-Image-Edit</td><td>指令编辑</td><td>显性纠错</td><td>中文/英文</td><td>云端</td><td>按次</td><td>快速验证诊断</td></tr><tr><td>W4 FLUX.2 dev</td><td>生成/编辑</td><td>参考基准</td><td>自然语言</td><td>租卡</td><td>按小时</td><td>校准上限</td></tr><tr><td>W5 老师风格</td><td>标签/参考/LoRA</td><td>风格模仿</td><td>混合</td><td>混合</td><td>混合</td><td>追特定画师</td></tr></tbody></table><h2 id="_4-对照方法" tabindex="-1">4. 对照方法</h2><ul><li>同一张画，各基线各出一版，归档&quot;同画多通道&quot;对照组（模板见 07）</li><li>固定种子，否则差异混杂随机性</li><li>所有通道都会正常化你的风格（表层复制）——&quot;错误 vs 风格差异&quot;分类照旧适用</li><li>先跑通，再谈优化（第 3–4 周目标：W2 跑通一张 + W5 路线 1 验证）</li></ul>',17)])])}const b=d(a,[["render",o]]);export{g as __pageData,b as default};
